<script setup>
import { ref } from 'vue'
import { useLearnerStore } from '@/stores/learner'
import { useRouter } from 'vue-router'
const learner=useLearnerStore(),router=useRouter(),message=ref(''),confirmReset=ref(false)
function download(){const blob=new Blob([JSON.stringify({version:2,exportedAt:new Date().toISOString(),state:learner.$state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='yuban-alex-learning.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message.value='学习档案已导出，请妥善保存。'}
async function upload(e){try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw new Error('档案过大，请检查文件');learner.importArchive(await file.text());message.value='已恢复学习档案。'}catch(err){message.value=err.message}finally{e.target.value=''}}
function reset(){learner.resetAll();router.push('/onboarding')}
</script>
<template><section class="profile-page"><header class="page-head"><div><h1>我的学习档案</h1><p>只为推荐更合适的内容，不用年级给你贴标签。</p></div></header><div class="panel profile-card"><img src="/assets/alex-mentor.png" alt="Alex"/><div><h2>{{learner.displayName}}</h2><p class="muted">{{learner.placementDone?`这850词中的初步认识量约${learner.summary.median}，区间${learner.summary.low}—${learner.summary.high}`:'还没有做基础测试'}}</p><RouterLink to="/onboarding" class="btn btn-secondary">修改学习需求</RouterLink></div></div><div class="panel archive"><h2>记录握在自己手里。</h2><p class="muted">当前记录保存在这个浏览器中，换设备前先导出。档案不含任何服务密钥。</p><div class="actions"><button class="btn btn-primary" @click="download">导出学习档案</button><label class="btn btn-secondary">恢复学习档案<input type="file" accept="application/json,.json" class="file-input" @change="upload"/></label><RouterLink class="btn btn-ghost" to="/placement">重新测评</RouterLink></div><p class="notice">重新测评会重新建立识读起点。建议先导出旧档案；不会把未测词自动标成已掌握。</p><p v-if="message||learner.storageError" role="status">{{message||learner.storageError}}</p></div><section class="scope"><h3>声音与AI服务</h3><p>个性化文章与对话通过服务器连接DeepSeek；未配置时会明确说明。当前朗读使用设备英语音色，录音提供回听和识别文本匹配，不冒充专业口音评分。</p><p>豆包实时语音、视觉通话和发音测评仍需火山服务开通与凭证，不在本次交付中伪装成已连接。</p></section><button class="btn btn-ghost" @click="confirmReset=true">清除本浏览器学习记录</button><div v-if="confirmReset" class="notice"><p>确认清除？清除后只有导出的档案可以恢复。</p><button class="btn btn-secondary" @click="confirmReset=false">保留记录</button> <button class="btn btn-primary" @click="reset">确认清除</button></div></section></template>
<style scoped>.profile-page{max-width:850px;margin:auto}.profile-card{display:flex;align-items:center;gap:25px;padding:30px}.profile-card img{width:75px}.profile-card h2{font-size:25px}.profile-card p{font-size:13px}.archive{padding:30px;margin:25px 0}.archive h2{font-size:23px;font-weight:500}.archive p,.scope p{font-size:13px}.file-input{position:absolute;width:1px;height:1px;opacity:0}.scope{padding:15px 5px;color:var(--ink-muted)}.scope h3{color:var(--ink);font-weight:500}</style>
